// Verificamos que el llamado venga de nuestra función de Netlify.
// El mismo valor va en la variable N8N_WEBHOOK_TOKEN de Netlify.
const TOKEN = $env.N8N_WEBHOOK_TOKEN || '';
const cabecera = $input.first().json.headers?.authorization || '';
if (TOKEN && cabecera !== 'Bearer ' + TOKEN) {
  throw new Error('No autorizado');
}

const cuerpo = $input.first().json.body || {};
const c = cuerpo.contexto || {};

const lista = (arr) => (arr || []).map(s =>
  `${s.fecha}: ${s.bloque} · ${s.series} series · ${s.minutos} min · ${s.kcal} kcal`
).join('\n') || 'Todavía no registró ninguna sesión.';

const ficha = [
  `Nombre: ${c.nombre || 'sin nombre'}`,
  `Sexo: ${c.sexo} · Edad: ${c.edad} años · Altura: ${c.altura_cm} cm`,
  `Peso actual: ${c.peso_kg} kg` + (c.cambio_peso_kg !== null && c.cambio_peso_kg !== undefined
      ? ` (arrancó en ${c.peso_inicial_kg} kg, ${c.cambio_peso_kg >= 0 ? '+' : ''}${c.cambio_peso_kg} kg)` : ''),
  c.cintura_cm ? `Cintura: ${c.cintura_cm} cm` : null,
  `Objetivo: ${c.objetivo} · Nivel: ${c.nivel}`,
  `Entrena: ${c.entrena_en}, ${c.dias_por_semana} días por semana`,
  `Sesiones completadas en total: ${c.sesiones_totales}`,
  c.cargas_actuales ? `Cargas que mueve hoy: ${c.cargas_actuales}` : null
].filter(Boolean).join('\n');

return [{
  json: {
    usuario_id: cuerpo.usuario_id,
    mensaje: cuerpo.mensaje,
    ficha,
    ultimas_sesiones: lista(c.ultimas_sesiones)
  }
}];
